package com.example

/**
 * Curated, 100% syllabus-aligned Flashcards for Health & Physical Education (සෞඛ්‍යය හා ශාරීරික).
 * Part 1: Categories 1 to 10 (20 distinct questions per category = 200 unique questions).
 */
object FlashcardBankHealthSetsPart1 {

  fun getHealthSet(s: Int, c: Int): CardContentTuple? {
    return when (s) {
      1 -> getSet1(c)
      2 -> getSet2(c)
      3 -> getSet3(c)
      4 -> getSet4(c)
      5 -> getSet5(c)
      6 -> getSet6(c)
      7 -> getSet7(c)
      8 -> getSet8(c)
      9 -> getSet9(c)
      10 -> getSet10(c)
      else -> null
    }
  }

  // Set 1: සෞඛ්‍ය සංකල්පය සහ මානව වර්ධනය (Health Concepts & Human Growth)
  private fun getSet1(c: Int): CardContentTuple = when (c) {
    1 -> CardContentTuple("ලෝක සෞඛ්‍ය සංවිධානය (WHO) අනුව සෞඛ්‍යය යන්න නිර්වචනය කරන්න.", "රෝගවලින් තොරවීම පමණක් නොව කායික, මානසික, සමාජීය සහ ආධ්‍යාත්මික වශයෙන් යහපැවැත්ම සම්පූර්ණ තත්ත්වයකි.", "විභාග උපදෙස: මානයන් 4 සම්පූර්ණ විය යුතුය.", "සෞඛ්‍යය • කාණ්ඩය 1")
    2 -> CardContentTuple("වර්ධනය (Growth) සහ සංවර්ධනය (Development) අතර වෙනස කුමක්ද?", "වර්ධනය යනු සිරුරේ උස, බර ආදී ප්‍රමාණාත්මක වෙනස්වීම්ය; සංවර්ධනය යනු කුසලතා හා චර්යාවන්හි ගුණාත්මක වෙනස්වීම්ය.", "විභාග උපදෙස: වර්ධනය මැනිය හැකි අතර සංවර්ධනය නිරීක්ෂණය කළ යුතුය.", "සෞඛ්‍යය • කාණ්ඩය 1")
    3 -> CardContentTuple("නව යොවුන් විය (Adolescence) ලෙස WHO හඳුන්වන වයස් සීමාව කුමක්ද?", "වයස අවුරුදු 10 සිට 19 දක්වා කාල සීමාවයි.", "විභාග උපදෙස: ශීඝ්‍ර වර්ධන පිම්මක් සිදුවන අවධියකි.", "සෞඛ්‍යය • කාණ්ඩය 1")
    4 -> CardContentTuple("නව යොවුන් වියේ පිරිමි ළමුන් තුළ දක්නට ලැබෙන ද්විතීයික ලිංගික ලක්ෂණ 2ක් දක්වන්න.", "හඬ ගොරෝසු වීම සහ රැවුල හා කිහිලි/යටිබඩ ප්‍රදේශයේ රෝම වර්ධනය වීම.", "විභාග උපදෙස: ටෙස්ටොස්ටෙරෝන් හෝමෝනය මඟින් පාලනය වේ.", "සෞඛ්‍යය • කාණ්ඩය 1")
    5 -> CardContentTuple("නව යොවුන් වියේ ගැහැණු ළමුන් තුළ දක්නට ලැබෙන ද්විතීයික ලිංගික ලක්ෂණ 2ක් දක්වන්න.", "පියයුරු වර්ධනය වීම, උකුල් ප්‍රදේශය පළල් වීම සහ ඔසප් වීම ආරම්භ වීම.", "විභාග උපදෙස: ඊස්ට්‍රජන් සහ ප්‍රොජෙස්ටරෝන් හෝමෝන මඟින් සිදුවේ.", "සෞඛ්‍යය • කාණ්ඩය 1")
    6 -> CardContentTuple("ඔසප් චක්‍රයක (Menstrual Cycle) සාමාන්‍ය දින ගණන කීයද?", "දින 28 කි (දින 21 සිට 35 දක්වා පරාසය සාමාන්‍ය වේ).", "විභාග උපදෙස: 14 වන දිනයේදී ඩිම්බ මෝචනය (Ovulation) සිදුවේ.", "සෞඛ්‍යය • කාණ්ඩය 1")
    7 -> CardContentTuple("නව යොවුන් වියේදී ඇතිවන මානසික සහ සමාජයීය වෙනස්කම් 2ක් දක්වන්න.", "ස්වාධීන වීමට ඇති කැමැත්ත සහ සම වයස් කණ්ඩායම්වල (Peer groups) මතයට වැඩි නැඹුරුවක් දැක්වීම.", "විභාග උපදෙස: හැඟීම් පාලනය පුහුණු කිරීම වැදගත් වේ.", "සෞඛ්‍යය • කාණ්ඩය 1")
    8 -> CardContentTuple("පුද්ගල සනීපාරක්ෂාව (Personal Hygiene) පවත්වා ගැනීමේ ප්‍රධාන පියවර 2ක් දක්වන්න.", "දිනපතා ස්නානය කිරීම සහ සබන් යොදා නිවැරදිව දෑත් සේදීම.", "විභාග උපදෙස: විෂබීජ ආසාදන වළක්වා ගැනීමට උපකාරී වේ.", "සෞඛ්‍යය • කාණ්ඩය 1")
    9 -> CardContentTuple("දත් දිරායාම (Dental Caries) වළක්වා ගැනීමට ගත හැකි ක්‍රියාමාර්ග 2ක් මොනවාද?", "දිනකට දෙවරක් ෆ්ලෝරයිඩ් සහිත දන්තාලේපයකින් දත් මැදීම සහ පැණිරස ආහාර භාවිතය සීමා කිරීම.", "විභාග උපදෙස: බැක්ටීරියා මඟින් නිපදවන අම්ල එනමලය දිය කරයි.", "සෞඛ්‍යය • කාණ්ඩය 1")
    10 -> CardContentTuple("ශරීර ස්කන්ධ දර්ශකය (BMI) ගණනය කරන සූත්‍රය කුමක්ද?", "BMI = බර (kg) / [උස (m) x උස (m)].", "විභාග උපදෙස: ඒකකය kg/m² වේ.", "සෞඛ්‍යය • කාණ්ඩය 1")
    11 -> CardContentTuple("නිරෝගී වැඩිහිටියෙකුගේ සාමාන්‍ය BMI අගය පරාසය කුමක්ද?", "18.5 සිට 24.9 දක්වා වේ.", "විභාග උපදෙස: 25 ට වැඩි නම් අධිබර වන අතර 30 ට වැඩි නම් ස්ථුලතාවයයි.", "සෞඛ්‍යය • කාණ්ඩය 1")
    12 -> CardContentTuple("මනා ඉරියව් (Good Posture) පවත්වා ගැනීමේ වැදගත්කම කුමක්ද?", "කොඳු ඇට පෙළේ ස්වභාවික වක්‍රතාව ආරක්ෂා වීම සහ පේශි හා සන්ධිවලට අනවශ්‍ය පීඩනයක් ඇති නොවීම.", "විභාග උපදෙස: සිරුරේ තෙහෙට්ටුව සහ වේදනා වළක්වයි.", "සෞඛ්‍යය • කාණ්ඩය 1")
    13 -> CardContentTuple("කය වෙහෙසා වැඩ කිරීම (Physical Activity) මඟින් සිරුරට ලැබෙන වාසියක් දක්වන්න.", "හෘද හා රුධිර නාල ක්‍රියාකාරිත්වය යහපත් වීම සහ අධික කැලරි දහනය වී බර පාලනය වීම.", "විභාග උපදෙස: දිනකට අවම විනාඩි 30ක ක්‍රියාකාරකම් නිර්දේශිතයි.", "සෞඛ්‍යය • කාණ්ඩය 1")
    14 -> CardContentTuple("සුවබර නින්දක් (Sound Sleep) නව යොවුන් දරුවෙකුට දිනකට පැය කීයක් අවශ්‍යද?", "පැය 8 සිට 10 දක්වා කාලයක්.", "විභාග උපදෙස: මොළයේ ක්‍රියාකාරිත්වය සහ වර්ධක හෝමෝන ශ්‍රාවය නිසි ලෙස සිදුවේ.", "සෞඛ්‍යය • කාණ්ඩය 1")
    15 -> CardContentTuple("ස්වයං සංකල්පය (Self-concept) යනු කුමක්ද?",
      "තමා පිළිබඳව තමා තුළම පවතින දැනුවත්භාවය, ආත්ම අභිමානය සහ ආකල්ප සමස්තයයි.", "විභාග උපදෙස: ධනාත්මක ආත්ම අභිමානය සාර්ථකත්වයට මඟ පාදයි.", "සෞඛ්‍යය • කාණ්ඩය 1")
